var sb = new System.Text.StringBuilder();
sb.Append("sceneCount=" + UnityEngine.SceneManagement.SceneManager.sceneCount).Append("\n");
for (int i = 0; i < UnityEngine.SceneManagement.SceneManager.sceneCount; i++)
{
    var sc = UnityEngine.SceneManagement.SceneManager.GetSceneAt(i);
    sb.Append("SCENE[").Append(i).Append("] ").Append(sc.name).Append(" path=").Append(sc.path).Append(" roots=").Append(sc.rootCount).Append(" loaded=").Append(sc.isLoaded).Append("\n");
    if (!sc.isLoaded) continue;
    foreach (var root in sc.GetRootGameObjects())
    {
        sb.Append("  ROOT: ").Append(root.name).Append("\n");
        foreach (var t in root.GetComponentsInChildren<Transform>(true))
        {
            if (t.name.StartsWith("Slot"))
            {
                var rt = t as RectTransform;
                string ap = rt == null ? "(no-rt)" : (rt.anchoredPosition.x + "," + rt.anchoredPosition.y);
                sb.Append("    [").Append(t.name).Append("] len=").Append(t.name.Length).Append(" anchored=").Append(ap).Append("\n");
            }
        }
    }
}
return sb.ToString();
